package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseP4MigrationTest extends MigrationTestSupport {
 @Test void legacyRatingsAndUnknownServiceProfessionAreNotConvertedIntoVerifiedReputation(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_p4_upgrade_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("78").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));try{UUID patient=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES('p4-legacy-patient@example.test','synthetic','ACTIVE') RETURNING id",UUID.class),pro=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES('p4-legacy-professional@example.test','synthetic','ACTIVE') RETURNING id",UUID.class);db.update("INSERT INTO professional_profiles(user_id,professional_type,title,verification_status,rating,green_ocean_score) VALUES(?,'PSYCHOLOGIST','Historical self declaration','PENDING',4.8,99)",pro);UUID review=db.queryForObject("INSERT INTO professional_reviews(professional_user_id,reviewer_user_id,rating,body,status) VALUES(?,?,5,'Historical unverified profile review','PUBLISHED') RETURNING id",UUID.class,pro,patient);UUID appointment=db.queryForObject("INSERT INTO consultation_requests(requester_user_id,professional_user_id,scheduled_at,consultation_mode,status) VALUES(?,?,CURRENT_TIMESTAMP,'TEXT','COMPLETED') RETURNING id",UUID.class,patient,pro);var before=db.queryForMap("SELECT rating,body,status FROM professional_reviews WHERE id=?",review);db.execute("CREATE TABLE clinic_feedback(synthetic_conflict INTEGER)");assertThatThrownBy(()->Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate()).isInstanceOf(Exception.class);assertThat(db.queryForObject("SELECT count(*) FROM information_schema.tables WHERE table_schema=? AND table_name='clinic_ranking_policies'",Integer.class,schema)).isZero();db.execute("DROP TABLE clinic_feedback");Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load().migrate();assertThat(db.queryForMap("SELECT rating,body,status FROM professional_reviews WHERE id=?",review)).isEqualTo(before);assertThat(db.queryForObject("SELECT profession_snapshot FROM consultation_requests WHERE id=?",String.class,appointment)).isNull();assertThat(db.queryForObject("SELECT count(*) FROM clinic_feedback",Integer.class)).isZero();assertThat(db.queryForObject("SELECT count(*) FROM clinic_ranking_policies",Integer.class)).isZero();}finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}}
}
